import sqlite3
from pathlib import Path

schema = Path('schema.sql').read_text(encoding='utf-8')
views = Path('views.sql').read_text(encoding='utf-8')

con = sqlite3.connect(':memory:')
con.executescript(schema)
con.executescript(views)
con.executescript("""
INSERT INTO customers VALUES (1, 'Ada', 'ada@example.com');
INSERT INTO products VALUES (1, 'Widget', 1000);
INSERT INTO orders VALUES (1, 1, 'paid', '2026-01-01');
INSERT INTO orders VALUES (2, 1, 'cancelled', '2026-01-02');
INSERT INTO order_items VALUES (1, 1, 1, 10, 1000);
INSERT INTO order_items VALUES (2, 2, 1, 5, 1000);
INSERT INTO order_discounts VALUES (1, 2, 100);
""")

row = con.execute(
    'SELECT total_cents FROM customer_order_totals WHERE customer_id = 1'
).fetchone()

assert row[0] == 10000, (
    f'expected total_cents 10000 (only the paid order counts, and the discount attached to the '
    f'cancelled order must NOT be subtracted since that order was already excluded), got {row[0]}')

